head.script:
scwin.screenId = "jldinf90300";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_objInstCd", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("objInstCd"))); } },
        { childId: "ipt_objInstNm", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("objInstNm"))); } },
        { childId: "ipt_ulyContn", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("ulyContn"))); } },
        { childId: "ipt_searchWord", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("searchWord"))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.util.getComponent("ipt_searchWord").focus();
        $c.util.getComponent('ipt_searchWord').setValue(($c.util.getComponent("ipt_searchWord").getValue() || ''));
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf90300.onpageload' }); }
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_submit). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_Search();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @description searchWord 을(를) 커서를 둔다 외
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf90300.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.ipt_searchWord_onkeyup
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.ipt_searchWord_onkeyup = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_searchWord_onkeyup — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        fn_boardCheck(selfVar)
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf90300.ipt_searchWord_onkeyup' }); }
};

/**
 * @event
 * @name scwin.btn_Search_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_Search_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_Search_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.search()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf90300.btn_Search_onclick' }); }
};

/**
 * @event
 * @name scwin.grd_resultList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_resultList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_resultList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_resultList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.send_form === 'function') { scwin.send_form(r["isurCd"], r["comNm"], r["stdCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.send_form (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.send_form'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_resultList.oncellclick' });
    }
};

/**
 * @event
 * @name scwin.btn_window_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_window_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_window_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.win.closePopup()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf90300.btn_window_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_window_onfocus
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_window_onfocus = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_window_onfocus — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        selfVar.blur()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf90300.btn_window_onfocus' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_Search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/common/undAssetList.do?method=undAssetList",
        ref: "dma_SearchReq",
        target: "dlt_resultList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldinf90300.tx_fn_Search" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @event
 * @name scwin.__on_enter_1_ipt_searchWord
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.__on_enter_1_ipt_searchWord = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin __on_enter_1_ipt_searchWord — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if(($c.util.getKeyCode(ev))==13){ await scwin.search() }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf90300.__on_enter_1_ipt_searchWord' }); }
};

/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    (document.JLDINF90300 || { elements: [] }).action = '/common/undAssetList.do?method=undAssetList';
    await scwin.tx_fn_Search();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.send_form
 * @author Inswave
 * @date 2026. 09. 29
 * @param isur_cd com_nm std_cd
 * @returns
 * @hidden N
*/
scwin.send_form = function (isur_cd, com_nm, std_cd) {
    /* sdd-asis-lifecycle:begin send_form — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const obj_inst_cd = $c.util.getComponent('dma_SearchReq').get('objInstCd');
    const obj_inst_nm = $c.util.getComponent('dma_SearchReq').get('objInstNm');
    const uly_contn = $c.util.getComponent('dma_SearchReq').get('ulyContn');
    if (isur_cd !== "") {
        (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById(obj_inst_cd)) || { setValue: function () {} }).setValue(isur_cd);
    }
    if (com_nm !== "") {
        (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById(obj_inst_nm)) || { setValue: function () {} }).setValue(com_nm);
    }
    if (std_cd !== "") {
        (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById(uly_contn)) || { setValue: function () {} }).setValue(std_cd);
    }
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};
